package local.ondemand;
import org.json.*;import java.util.*;import java.text.Normalizer;
/** Explainable movie matching from supplied metadata, with bounded genre-catalog requests. */
final class SimilarMovies {
 static String normal(String s){return Normalizer.normalize(s,Normalizer.Form.NFKD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+"," ").trim();}
 static Set<String> values(JSONObject m,String key){Set<String> out=new LinkedHashSet<>();Object value=m.opt(key);if(value instanceof JSONArray){JSONArray array=(JSONArray)value;for(int i=0;i<array.length();i++){String v=normal(array.optString(i));if(!v.isEmpty())out.add(v);}}else if(value!=null&&value!=JSONObject.NULL)for(String v:String.valueOf(value).split(",")){String n=normal(v);if(!n.isEmpty())out.add(n);}return out;}
 static int shared(Set<String> a,Set<String> b){int n=0;for(String v:a)if(b.contains(v))n++;return n;}
 static Set<String> words(String plot){Set<String> out=new HashSet<>();Set<String> stop=new HashSet<>(Arrays.asList("about","after","again","against","along","another","around","before","being","between","could","during","family","finds","first","their","there","these","those","through","together","until","where","which","while","world","would","young","story","life","lives","must","with","that","this","from","have","into","they","them","when","will","becomes","himself","herself"));for(String w:normal(plot).split(" "))if(w.length()>=4&&!stop.contains(w))out.add(w);return out;}
 static int minutes(JSONObject movie){String runtime=movie.optString("runtime","").trim();java.util.regex.Matcher m=java.util.regex.Pattern.compile("^(\\d+)(?:\\s*(?:min|minutes?))?$",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(runtime);try{return m.find()?Integer.parseInt(m.group(1)):0;}catch(Exception ignored){return 0;}}
 static int score(JSONObject source,JSONObject candidate){if(source.optString("id").equals(candidate.optString("id"))||!candidate.optString("type","movie").equals("movie")||candidate.optString("id").isEmpty()||candidate.optString("poster").isEmpty()||EpisodeInfo.upcoming(candidate)||minutes(source)>=60&&minutes(candidate)>0&&minutes(candidate)<40)return -1;Set<String> genres=values(source,"genres"),other=values(candidate,"genres");int overlap=shared(genres,other),directors=shared(values(source,"director"),values(candidate,"director"));if(overlap==0&&directors==0)return -1;int score=overlap*9+directors*(overlap>0?28:14)+Math.min(3,shared(values(source,"cast"),values(candidate,"cast")))*6;score-=Math.max(0,other.size()-overlap)*2;score+=Math.min(5,shared(words(source.optString("description")),words(candidate.optString("description"))));int a=DiscoverFilter.year(source),b=DiscoverFilter.year(candidate);if(a>0&&b>0){int gap=Math.abs(a-b);score+=gap<=5?5:gap<=12?3:gap<=25?1:0;}return score;}
 static List<JSONObject> rank(JSONObject source,List<JSONObject> pool){Map<String,JSONObject> unique=new LinkedHashMap<>();for(JSONObject movie:pool)if(score(source,movie)>=0&&!unique.containsKey(movie.optString("id")))unique.put(movie.optString("id"),movie);List<JSONObject> out=new ArrayList<>(unique.values());out.sort((a,b)->{int c=Integer.compare(score(source,b),score(source,a));return c!=0?c:a.optString("name").compareToIgnoreCase(b.optString("name"));});return new ArrayList<>(out.subList(0,Math.min(12,out.size())));}
 static List<JSONObject> find(Api api,JSONObject source,java.util.function.BooleanSupplier active)throws Exception{JSONArray genres=source.optJSONArray("genres");if(genres==null)genres=new JSONArray();List<JSONObject> pool=new ArrayList<>();boolean success=false;Exception problem=null;String filmmaker="";Object director=source.opt("director");if(director instanceof JSONArray)filmmaker=((JSONArray)director).optString(0);else if(director instanceof String)filmmaker=((String)director).split(",")[0].trim();if(!filmmaker.isEmpty()&&active.getAsBoolean())try{JSONArray data=api.similarFilmmaker(filmmaker);success=true;if(data!=null)for(int n=0;n<Math.min(50,data.length());n++){JSONObject movie=data.optJSONObject(n);if(movie!=null)pool.add(movie);}}catch(Exception e){problem=e;}Set<String> used=new HashSet<>();for(int i=0;i<genres.length()&&used.size()<2;i++){if(!active.getAsBoolean()||Thread.currentThread().isInterrupted())return new ArrayList<>();String genre=genres.optString(i);if(genre.isEmpty()||!used.add(genre))continue;try{JSONArray data=api.similarCatalog(genre);success=true;if(data!=null)for(int n=0;n<Math.min(50,data.length());n++){JSONObject movie=data.optJSONObject(n);if(movie!=null)pool.add(movie);}}catch(Exception e){problem=e;}}if(pool.isEmpty()&&problem!=null)throw problem;return rank(source,pool);}
}
